/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `dbtruck`.`trigger_layak_or_tidak layak` AFTER INSERT ON `dbtruck`.`tb_ceklist` FOR EACH ROW BEGIN
INSERT INTO tb_tidak_layak (transporter,value)
select new.nama_transporter,"1" from tb_ceklist
where new.hasil_pemeriksaan="Tidak Layak di Operasikan (Stiker Merah)"
ORDER BY new.tgbaca desc limit 1;
INSERT INTO tb_trigger_perlu_perbaikan (transporter,value)
select new.nama_transporter,"1" from tb_ceklist
where new.hasil_pemeriksaan="Perlu Perbaikan (Stiker Kuning)"
ORDER BY new.tgbaca desc limit 1;
INSERT INTO tb_trigger_tolak (transporter,value)
select new.nama_transporter,"1" from tb_ceklist
where new.hasil_pemeriksaan="Di Tolak di Pos 1"
ORDER BY new.tgbaca desc limit 1;
INSERT INTO tb_kelengkapan_tolak_pos1 (kelengkapan,value)
SELECT "Kondisi Ban Utama",1 FROM tb_ceklist
where new.utama1=0
ORDER BY new.tgbaca desc limit 1;
INSERT INTO tb_kelengkapan_tolak_pos1 (kelengkapan,value)
SELECT "Kebocoran REM",1 FROM tb_ceklist
where new.utama2=0
ORDER BY new.tgbaca desc limit 1;
