/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `smartlogistic`.`tbl_batch_counter_before_insert` BEFORE INSERT ON `tbl_batch_counter` FOR EACH ROW BEGIN
SELECT batch_counter, batch_prefix INTO @last_count, @last_prefix FROM tbl_batch_counter ORDER BY rec_date DESC LIMIT 1;
SET NEW.batch_counter = @last_count + 1;
SET NEW.rec_date = CURRENT_TIMESTAMP();
IF RIGHT(NEW.batch_counter,3) = '000' THEN
IF @last_prefix = 'Z' THEN
SET NEW.batch_prefix = 'A';
ELSE
SET NEW.batch_prefix = CHAR(ASCII(@last_prefix) + 1);
END IF;
ELSE
SET NEW.batch_prefix = @last_prefix;
END IF;
SET NEW.gr_date = CURRENT_DATE;
SET NEW.batch = CONCAT_WS('',DATE_FORMAT(NEW.gr_date, '%y%m%d'),NEW.batch_prefix,LPAD(RIGHT(NEW.batch_counter,3),3,'0'));
END 
*/;;
DELIMITER ;
