/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `smartlogistic`.`tbl_item_pengiriman_before_insert` BEFORE UPDATE ON `tbl_item_pengiriman` FOR EACH ROW BEGIN
	IF NEW.qty_hasil_hpk > 0 
		
		AND NEW.setuju_terima = 'Y' 
		AND NEW.on_schedule IS NOT NULL 
		AND NEW.packing_condition IS NOT NULL
		AND NEW.unload_ok IS NOT NULL 
		AND NEW.id_label_exist IS NOT NULL 
		AND NEW.safety_label_exist IS NOT NULL 
		THEN
			SET NEW.gr_ready = 'Y';
	ELSE
		
		SET NEW.gr_ready = 'N';
	END IF;
END 
*/;;
DELIMITER ;
